// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.6.12;

/// @title DaiJoin - Bridge between DAI token and Vat accounting units
contract DaiJoin {
    // ========================================================================
    // STORAGE
    // ========================================================================

    /// @notice Authorization mapping: address => permitted (1 = authorized, 0 = not)
    mapping(address => uint256) public wards;

    /// @notice Address of the Vat contract (internal accounting system)
    address public vat;

    /// @notice Address of the DAI token contract
    address public dai;

    /// @notice Live flag: 1 = contract is active, 0 = contract is shut down
    uint256 public live;

    // ========================================================================
    // EVENTS
    // ========================================================================

    /// @notice Emitted on all state-changing functions for off-chain tracking
    event LogNote(
        bytes4 indexed sig,
        address indexed usr,
        bytes32 arg1,
        bytes32 arg2,
        bytes data
    ) anonymous;

    // ========================================================================
    // MODIFIERS
    // ========================================================================

    /// @notice Restricts function access to authorized addresses only
    modifier auth {
        require(wards[msg.sender] == 1, "DaiJoin/not-authorized");
        _;
    }

    /// @notice Ensures contract is still live/active
    modifier liveCheck {
        require(live == 1, "DaiJoin/not-live");
        _;
    }

    // ========================================================================
    // CONSTRUCTOR & FALLBACK
    // ========================================================================

    /// @notice Constructor - initializes storage (deployment details omitted in decompilation)
    constructor(address vat_, address dai_) public {
        vat = vat_;
        dai = dai_;
        live = 1;
        wards[msg.sender] = 1;
    }

    /// @notice Fallback function - always reverts
    receive() external payable {
        revert();
    }

    // ========================================================================
    // ADMINISTRATION FUNCTIONS
    // ========================================================================

    /// @notice Grant authorization to an address
    /// @param usr Address to authorize
    function rely(address usr) external auth {
        wards[usr] = 1;
        _logNote(msg.sender, usr);
    }

    /// @notice Revoke authorization from an address
    /// @param usr Address to deauthorize
    function deny(address usr) external auth {
        wards[usr] = 0;
        _logNote(msg.sender, usr);
    }

    /// @notice Shut down the contract (set live to 0)
    /// @notice Can only be called by authorized addresses
    function cage() external auth {
        live = 0;
        _logNote(msg.sender);
    }

    // ========================================================================
    // CORE FUNCTIONS
    // ========================================================================

    /// @notice Join DAI tokens into the Vat system
    /// @dev Transfers DAI from msg.sender to this contract, then credits 
    ///      internal accounting units to usr in the Vat
    /// @param usr Address to credit in the Vat
    /// @param wad Amount of DAI (in wei, 18 decimals) to join
    function join(address usr, uint256 wad) external {
        require(calldata.length >= 68, "DaiJoin/invalid-calldata");

        if (wad == 0) {
            // No-op join for zero amount
            require(vat.code.length > 0, "DaiJoin/vat-not-deployed");
            (bool success,) = vat.call(
                abi.encodeWithSignature(
                    "move(address,address,uint256)",
                    address(this),
                    usr,
                    0
                )
            );
            require(success, "DaiJoin/vat-call-failed");
        } else {
            // Validate wad doesn't overflow when scaled
            require(wad > 0, "DaiJoin/zero-wad");
            require(
                1000000000 * 10**18 * wad / wad == 1000000000 * 10**18,
                "DaiJoin/overflow"
            );

            require(vat.code.length > 0, "DaiJoin/vat-not-deployed");
            (bool success,) = vat.call(
                abi.encodeWithSignature(
                    "move(address,address,uint256)",
                    address(this),
                    usr,
                    1000000000 * 10**18 * wad
                )
            );
            require(success, "DaiJoin/vat-call-failed");
        }

        // Transfer DAI from caller to this contract
        require(dai.code.length > 0, "DaiJoin/dai-not-deployed");
        (success,) = dai.call(
            abi.encodeWithSignature(
                "transferFrom(address,address,uint256)",
                msg.sender,
                address(this),
                wad
            )
        );
        require(success, "DaiJoin/dai-transfer-failed");

        _logNote(msg.sender, usr, bytes32(wad));
    }

    /// @notice Exit DAI tokens from the Vat system
    /// @dev Debits internal accounting units from msg.sender in the Vat,
    ///      then mints/transfers DAI to usr
    /// @param usr Address to receive DAI tokens
    /// @param wad Amount of DAI (in wei, 18 decimals) to exit
    function exit(address usr, uint256 wad) external liveCheck {
        require(calldata.length >= 68, "DaiJoin/invalid-calldata");

        if (wad == 0) {
            // No-op exit for zero amount
            require(vat.code.length > 0, "DaiJoin/vat-not-deployed");
            (bool success,) = vat.call(
                abi.encodeWithSignature(
                    "move(address,address,uint256)",
                    msg.sender,
                    address(this),
                    0
                )
            );
            require(success, "DaiJoin/vat-call-failed");
        } else {
            // Validate wad doesn't overflow when scaled
            require(wad > 0, "DaiJoin/zero-wad");
            require(
                1000000000 * 10**18 * wad / wad == 1000000000 * 10**18,
                "DaiJoin/overflow"
            );

            require(vat.code.length > 0, "DaiJoin/vat-not-deployed");
            (bool success,) = vat.call(
                abi.encodeWithSignature(
                    "move(address,address,uint256)",
                    msg.sender,
                    address(this),
                    1000000000 * 10**18 * wad
                )
            );
            require(success, "DaiJoin/vat-call-failed");
        }

        // Mint/transfer DAI to usr
        require(dai.code.length > 0, "DaiJoin/dai-not-deployed");
        (success,) = dai.call(
            abi.encodeWithSignature(
                "mint(address,uint256)",
                usr,
                wad
            )
        );
        require(success, "DaiJoin/dai-mint-failed");

        _logNote(msg.sender, usr, bytes32(wad));
    }

    // ========================================================================
    // INTERNAL HELPERS
    // ========================================================================

    /// @notice Internal logging helper for consistent event emission
    function _logNote(
        address usr,
        address target,
        bytes32 data
    ) internal {
        assembly {
            log4(
                0,
                224,
                calldataload(0),
                usr,
                target,
                data
            )
        }
    }

    /// @notice Internal logging helper (2 parameters)
    function _logNote(address usr, address target) internal {
        assembly {
            log4(
                0,
                224,
                calldataload(0),
                usr,
                target,
                0
            )
        }
    }

    /// @notice Internal logging helper (1 parameter)
    function _logNote(address usr) internal {
        assembly {
            log4(
                0,
                224,
                calldataload(0),
                usr,
                0,
                0
            )
        }
    }
}
