// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.0;

/**
 * @title DssLitePsm - Lightweight Parity Stability Module
 * @notice A simplified PSM for swapping between DAI and USDC with optional fees
 */
contract DssLitePsm {
    // ========================================================================
    // STORAGE
    // ========================================================================

    /// @notice Authorization mapping: addr => authorized (1/0)
    mapping(address => uint256) public wards;

    /// @notice Whitelist mapping: addr => whitelisted (1/0)
    mapping(address => uint256) public bud;

    /// @notice Address of the Vow contract (surplus buffer)
    address public vow;

    /// @notice Sell fee rate (in basis points, 10^18 precision)
    uint256 public tin;

    /// @notice Buy fee rate (in basis points, 10^18 precision)
    uint256 public tout;

    /// @notice Buffer amount
    uint256 public buf;

    // ========================================================================
    // CONSTANTS
    // ========================================================================

    address private constant VAT           = 0x35d1b3f3d7966a1dfe207aa4514c12a259a0492b;
    address private constant USDC          = 0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48;
    address private constant DAI           = 0x6b175474e89094c44da98b954eedeac495271d0f;
    address private constant GEM_JOIN      = 0x9759a6ac90977b93b58547b4a71c78317f391a28;
    address private constant POOL_ADDRESS  = 0x37305b1cd40574e4c5ce33f8e8306be057fd7341;
    bytes32  private constant ILK          = "LITE-PSM-USDC-A";

    uint256 private constant PRECISION     = 1e12;  // USDC has 6 decimals, DAI has 18
    uint256 private constant WAD           = 1e18;
    uint256 private constant MAX_RATE      = 1e18;  // Maximum fee rate

    // ========================================================================
    // EVENTS
    // ========================================================================

    event Rely(address indexed usr);
    event Deny(address indexed usr);
    event Diss(address indexed a);
    event BudSet(address indexed usr, uint256 enabled);
    event File(bytes32 indexed what, uint256 data);
    event SellGem(address indexed usr, uint256 gemAmount, uint256 daiAmount);
    event BuyGem(address indexed usr, uint256 gemAmount, uint256 daiAmount);
    event Chug(uint256 amount);

    // ========================================================================
    // MODIFIERS
    // ========================================================================

    modifier auth() {
        require(wards[msg.sender] == 1, "DssLitePsm/not-authorized");
        _;
    }

    modifier whitelisted() {
        require(bud[msg.sender] == 1, "DssLitePsm/not-whitelisted");
        _;
    }

    // ========================================================================
    // VIEW FUNCTIONS
    // ========================================================================

    /// @notice Check if address is authorized
    function wards(address usr) external view returns (uint256) {
        return wards[usr];
    }

    /// @notice Get current sell fee rate
    function tin() external view returns (uint256) {
        return tin;
    }

    /// @notice Get current buy fee rate
    function tout() external view returns (uint256) {
        return tout;
    }

    /// @notice Get buffer amount
    function buf() external view returns (uint256) {
        return buf;
    }

    /// @notice Get Vow address
    function vow() external view returns (address) {
        return vow;
    }

    // ========================================================================
    // AUTHORIZATION FUNCTIONS
    // ========================================================================

    /// @notice Authorize an address
    function rely(address usr) external auth {
        wards[usr] = 1;
        emit Rely(usr);
    }

    /// @notice Deauthorize an address
    function deny(address usr) external auth {
        wards[usr] = 0;
        emit Deny(usr);
    }

    /// @notice Remove authorization for caller
    function diss(address a) external auth {
        bud[a] = 0;
        emit Diss(a);
    }

    /// @notice Add address to whitelist
    function setBud(address usr, uint256 enabled) external auth {
        bud[usr] = enabled;
        emit BudSet(usr, enabled);
    }

    // ========================================================================
    // CONFIGURATION FUNCTIONS
    // ========================================================================

    /// @notice Set configuration parameters
    /// @param what Parameter name as bytes32 ("tin", "tout", or "buf")
    /// @param data New value
    function file(bytes32 what, uint256 data) external auth {
        if (what == "tin") {
            require(data == type(uint256).max || data <= MAX_RATE, "DssLitePsm/tin-out-of-range");
            tin = data;
        } else if (what == "tout") {
            require(data == type(uint256).max || data <= MAX_RATE, "DssLitePsm/tout-out-of-range");
            tout = data;
        } else if (what == "buf") {
            buf = data;
        } else {
            revert("DssLitePsm/file-unrecognized-param");
        }
        emit File(what, data);
    }

    /// @notice Set Vow address
    function fileVow(address newVow) external auth {
        vow = newVow;
        emit File("vow", uint256(uint160(newVow)));
    }

    // ========================================================================
    // CORE PSM FUNCTIONS
    // ========================================================================

    /// @notice Sell USDC for DAI (with fee)
    /// @param usr Recipient of DAI
    /// @param gemAmount Amount of USDC to sell (6 decimals)
    /// @return daiAmount Amount of DAI received (18 decimals)
    function sellGem(address usr, uint256 gemAmount) external whitelisted returns (uint256 daiAmount) {
        require(tin != type(uint256).max, "DssLitePsm/sell-gem-halted");

        // Overflow check
        require(gemAmount == 0 || PRECISION <= type(uint256).max / gemAmount, "overflow");

        // Transfer USDC from caller to pool
        _transferUSDC(msg.sender, POOL_ADDRESS, gemAmount);

        // Calculate DAI amount with fee
        daiAmount = gemAmount * PRECISION;
        if (tin > 0) {
            uint256 fee = (daiAmount * tin) / WAD;
            daiAmount = daiAmount - fee;
        }

        // Transfer DAI to recipient
        _transferDAI(usr, daiAmount);

        emit SellGem(usr, gemAmount, daiAmount);
        return daiAmount;
    }

    /// @notice Buy USDC with DAI (with fee)
    /// @param usr Recipient of USDC
    /// @param daiAmount Amount of DAI to spend (18 decimals)
    /// @return gemAmount Amount of USDC received (6 decimals)
    function buyGem(address usr, uint256 daiAmount) external whitelisted returns (uint256 gemAmount) {
        require(tout != type(uint256).max, "DssLitePsm/buy-gem-halted");

        // Overflow check
        require(daiAmount == 0 || PRECISION <= type(uint256).max / daiAmount, "overflow");

        // Transfer DAI from caller to this contract
        _transferDAIFrom(msg.sender, address(this), daiAmount);

        // Calculate USDC amount
        gemAmount = daiAmount / PRECISION;

        // Transfer USDC from pool to recipient
        _transferUSDCFrom(POOL_ADDRESS, usr, gemAmount);

        emit BuyGem(usr, gemAmount, daiAmount);
        return gemAmount;
    }

    /// @notice Sell USDC for DAI (legacy function with fee logic)
    /// @param usr Recipient of DAI
    /// @param gemAmount Amount of USDC to sell (6 decimals)
    /// @return daiAmount Amount of DAI received (18 decimals)
    function sellGemLegacy(address usr, uint256 gemAmount) external returns (uint256 daiAmount) {
        require(tin + 1 > 0, "DssLitePsm/sell-gem-halted");

        // Overflow check
        require(gemAmount == 0 || PRECISION <= type(uint256).max / gemAmount, "overflow");

        // Transfer USDC from caller to pool
        _transferUSDC(msg.sender, POOL_ADDRESS, gemAmount);

        if (tin == 0) {
            // No fee
            daiAmount = gemAmount * PRECISION;
            _transferDAI(usr, daiAmount);
        } else {
            // With fee
            require(
                gemAmount * PRECISION == 0 || 
                tin <= type(uint256).max / (gemAmount * PRECISION),
                "overflow"
            );

            daiAmount = gemAmount * PRECISION;
            uint256 fee = (daiAmount * tin) / WAD;
            daiAmount = daiAmount - fee;

            _transferDAI(usr, daiAmount);
        }

        emit SellGem(usr, gemAmount, daiAmount);
        return daiAmount;
    }

    // ========================================================================
    // SURPLUS MANAGEMENT
    // ========================================================================

    /// @notice Calculate available surplus
    /// @return Available amount that can be chugged
    function getSurplus() external view returns (uint256) {
        // Get DAI balance of this contract
        uint256 daiBalance = _getDAIBalance(address(this));

        // Get USDC balance of pool
        uint256 usdcBalance = _getUSDCBalance(POOL_ADDRESS);

        // Overflow checks
        require(usdcBalance == 0 || PRECISION <= type(uint256).max / usdcBalance, "overflow");
        require(usdcBalance * PRECISION <= type(uint256).max / 1000000000001, "overflow");

        uint256 targetDai = (usdcBalance * PRECISION * 1000000000001) / 1e12;

        if (daiBalance < targetDai) {
            return daiBalance;
        }

        return targetDai - daiBalance;
    }

    /// @notice Transfer surplus to Vow
    function chug() external {
        require(vow != address(0), "DssLitePsm/chug-missing-vow");

        uint256 surplus = getSurplusInternal();

        if (surplus == 0) {
            revert("DssLitePsm/nothing-to-chug");
        }

        // Join DAI to Vat and transfer to Vow
        _joinAndTransferToVow(surplus);

        emit Chug(surplus);
    }

    /// @notice Internal function to calculate surplus
    function getSurplusInternal() internal view returns (uint256) {
        uint256 daiBalance = _getDAIBalance(address(this));
        uint256 usdcBalance = _getUSDCBalance(POOL_ADDRESS);

        require(usdcBalance == 0 || PRECISION <= type(uint256).max / usdcBalance, "overflow");
        require(usdcBalance * PRECISION <= type(uint256).max / 1000000000001, "overflow");

        uint256 targetDai = (usdcBalance * PRECISION * 1000000000001) / 1e12;

        if (daiBalance < targetDai) {
            return daiBalance;
        }

        return targetDai - daiBalance;
    }

    // ========================================================================
    // INTERNAL HELPERS
    // ========================================================================

    function _transferUSDC(address from, address to, uint256 amount) internal {
        (bool success, ) = USDC.call(
            abi.encodeWithSignature(
                "transferFrom(address,address,uint256)",
                from,
                to,
                amount
            )
        );
        require(success, "USDC transfer failed");
    }

    function _transferUSDCFrom(address from, address to, uint256 amount) internal {
        (bool success, ) = USDC.call(
            abi.encodeWithSignature(
                "transferFrom(address,address,uint256)",
                from,
                to,
                amount
            )
        );
        require(success, "USDC transferFrom failed");
    }

    function _transferDAI(address to, uint256 amount) internal {
        (bool success, ) = DAI.call(
            abi.encodeWithSignature(
                "transfer(address,uint256)",
                to,
                amount
            )
        );
        require(success, "DAI transfer failed");
    }

    function _transferDAIFrom(address from, address to, uint256 amount) internal {
        (bool success, ) = DAI.call(
            abi.encodeWithSignature(
                "transferFrom(address,address,uint256)",
                from,
                to,
                amount
            )
        );
        require(success, "DAI transferFrom failed");
    }

    function _getDAIBalance(address account) internal view returns (uint256) {
        (bool success, bytes memory data) = DAI.staticcall(
            abi.encodeWithSignature(
                "balanceOf(address)",
                account
            )
        );
        require(success, "DAI balanceOf failed");
        require(data.length >= 32, "invalid balanceOf response");
        return abi.decode(data, (uint256));
    }

    function _getUSDCBalance(address account) internal view returns (uint256) {
