        uint256 line;     // field_768 - Debt ceiling
        uint256 dust;     // field_1024 - Minimum debt
    }
    mapping(bytes32 => Ilk) public ilks;

    /// @dev Urn data structure (slot 3)
    struct Urn {
        uint256 ink;      // field_0   - Collateral amount
        uint256 art;      // field_256 - Normalized debt
    }
    mapping(bytes32 => mapping(address => Urn)) public urns;

    /// @dev Gem (collateral) balances: ilk => usr => amount (slot 4)
    mapping(bytes32 => mapping(address => uint256)) public gem;

    /// @dev DAI balances: usr => amount (slot 5)
    mapping(address => uint256) public dai;

    /// @dev SIN (debt) balances: usr => amount (slot 6)
    mapping(address => uint256) public sin;

    /// @dev Total system debt (slot 7)
    uint256 public debt;

    /// @dev Total system vice (slot 8)
    uint256 public vice;

    /// @dev Global debt ceiling (slot 9)
    uint256 public Line;

    /// @dev System live flag (slot 10)
    uint256 public live;

    // ========================================================================
    // EVENTS
    // ========================================================================

    event LogNote(
        bytes4 sig,
        address indexed usr,
        bytes32 indexed arg1,
        bytes32 indexed arg2,
        uint256 data
    );

    // ========================================================================
    // MODIFIERS
    // ========================================================================

    modifier auth() {
        require(wards[msg.sender] == 1, "Vat/not-authorized");
        _;
    }

    modifier liveCheck() {
        require(live == 1, "Vat/not-live");
        _;
    }

    // ========================================================================
    // VIEW FUNCTIONS
    // ========================================================================

    /// @notice Check if address can act on behalf of another
    function can(address usr, address guy) external view returns (uint256) {
        return can[usr][guy];
    }

    /// @notice Get collateral balance for usr in ilk
    function gem(bytes32 ilk, address usr) external view returns (uint256) {
        return gem[ilk][usr];
    }

    /// @notice Get urn data for usr in ilk
    function urns(bytes32 ilk, address usr) 
        external 
        view 
        returns (uint256 ink, uint256 art) 
    {
        Urn storage u = urns[ilk][usr];
        return (u.ink, u.art);
    }

    /// @notice Get ilk data
    function ilks(bytes32 ilk) 
        external 
        view 
        returns (
            uint256 Art,
            uint256 rate,
            uint256 spot,
            uint256 line,
            uint256 dust
        ) 
    {
        Ilk storage i = ilks[ilk];
        return (i.Art, i.rate, i.spot, i.line, i.dust);
    }

    // ========================================================================
    // ADMIN FUNCTIONS
    // ========================================================================

    /// @notice Authorize an address
    function rely(address usr) external auth liveCheck {
        wards[usr] = 1;
        _logNote("rely", usr);
    }

    /// @notice Deauthorize an address
    function deny(address usr) external auth liveCheck {
        wards[usr] = 0;
        _logNote("deny", usr);
    }

    /// @notice Set global debt ceiling
    function file(bytes32 what, uint256 data) external auth liveCheck {
        require(keccak256(abi.encodePacked(what)) == keccak256(abi.encodePacked("Line")), 
                "Vat/file-unrecognized-param");
        Line = data;
        _logNote("file", what, data);
    }

    /// @notice Set ilk parameters
    function file(bytes32 ilk, bytes32 what, uint256 data) external auth liveCheck {
        if (keccak256(abi.encodePacked(what)) == keccak256(abi.encodePacked("spot"))) {
            ilks[ilk].spot = data;
        } else if (keccak256(abi.encodePacked(what)) == keccak256(abi.encodePacked("line"))) {
            ilks[ilk].line = data;
        } else if (keccak256(abi.encodePacked(what)) == keccak256(abi.encodePacked("dust"))) {
            ilks[ilk].dust = data;
        } else {
            revert("Vat/file-unrecognized-param");
        }
        _logNote("file", ilk, what, data);
    }

    /// @notice Initialize an ilk
    function init(bytes32 ilk) external auth {
        require(ilks[ilk].rate == 0, "Vat/ilk-already-init");
        ilks[ilk].rate = 1000000000 * 10**18;
        _logNote("init", ilk);
    }

    /// @notice Cage the system (emergency shutdown)
    function cage() external auth {
        live = 0;
        _logNote("cage");
    }

    // ========================================================================
    // AUTHORIZATION FUNCTIONS
    // ========================================================================

    /// @notice Allow address to act on behalf of caller
    function hope(address usr) external {
        can[msg.sender][usr] = 1;
        _logNote("hope", usr);
    }

    /// @notice Revoke authorization
    function nope(address usr) external {
        can[msg.sender][usr] = 0;
        _logNote("nope", usr);
    }

    // ========================================================================
    // CORE ACCOUNTING FUNCTIONS
    // ========================================================================

    /// @notice Move collateral between users within an ilk
    function flux(bytes32 ilk, address src, address dst, uint256 wad) external {
        require(src == msg.sender || can[src][msg.sender] == 1, "Vat/not-allowed");
        require(gem[ilk][src] >= wad, "Vat/overflow");

        gem[ilk][src] -= wad;
        gem[ilk][dst] += wad;

        _logNote("flux", ilk, src, dst, wad);
    }

    /// @notice Move DAI between users
    function move(address src, address dst, uint256 rad) external {
        require(src == msg.sender || can[src][msg.sender] == 1, "Vat/not-allowed");
        require(dai[src] >= rad, "Vat/overflow");

        dai[src] -= rad;
        dai[dst] += rad;

        _logNote("move", src, dst, rad);
    }

    /// @notice Internal DAI mint (admin only)
    function slip(bytes32 ilk, address usr, int256 wad) external auth {
        if (wad < 0) {
            require(gem[ilk][usr] >= uint256(-wad), "Vat/overflow");
        }
        gem[ilk][usr] = addInt(gem[ilk][usr], wad);
        _logNote("slip", ilk, usr, uint256(wad));
    }

    /// @notice Adjust internal debt (admin only)
    function fold(bytes32 ilk, address u, int256 rate_) external auth liveCheck {
        require(rate_ >= 0, "Vat/invalid-rate");

        Ilk storage i = ilks[ilk];
        require(i.rate > 0, "Vat/ilk-not-init");

        // Safe multiplication check
        if (rate_ != 0) {
            require(i.Art * uint256(rate_) / uint256(rate_) == i.Art, "Vat/overflow");
        }

        int256 change = i.Art * rate_;

        if (change < 0) {
            require(dai[u] >= uint256(-change), "Vat/overflow");
        }
        dai[u] = addInt(dai[u], change);

        i.rate = uint256(int256(i.rate) + rate_);

        if (change < 0) {
            require(debt >= uint256(-change), "Vat/overflow");
        }
        debt = uint256(int256(debt) + change);

        _logNote("fold", ilk, u, uint256(rate_));
    }

    // ========================================================================
    // DEBT ACCOUNTING
    // ========================================================================

    /// @notice Mint DAI and increase debt (internal)
    function suck(address u, address v, uint256 rad) external auth {
        sin[u] += rad;
        dai[v] += rad;
        vice += rad;
        debt += rad;
        _logNote("suck", u, v, rad);
    }

    /// @notice Burn DAI and decrease debt (internal)
    function spit(address u, address v, uint256 rad) external auth {
        require(sin[u] >= rad, "Vat/overflow");
        require(debt >= rad, "Vat/overflow");

        sin[u] -= rad;
        dai[v] -= rad;
        vice -= rad;
        debt -= rad;

        _logNote("spit", u, v, rad);
    }

    // ========================================================================
    // COLLATERAL & DEBT MANAGEMENT
    // ========================================================================

    /// @notice Modify urn (collateral and debt)
    function fork(bytes32 ilk, address src, address dst, int256 dink, int256 dart) external {
        require(src == msg.sender || can[src][msg.sender] == 1, "Vat/not-allowed");

        Urn storage s = urns[ilk][src];
        Urn storage d = urns[ilk][dst];
        Ilk storage i = ilks[ilk];

        // Update collateral
        if (dink < 0) {
            require(s.ink >= uint256(-dink), "Vat/overflow");
        }
        s.ink = addInt(s.ink, dink);
        d.ink = addInt(d.ink, dink);

        // Update debt
        if (dart < 0) {
            require(s.art >= uint256(-dart), "Vat/overflow");
        }
        s.art = addInt(s.art, dart);
        d.art = addInt(d.art, dart);

        // Update total debt
        int256 rateChange = i.Art * dart;
        if (rateChange < 0) {
            require(debt >= uint256(-rateChange), "Vat/overflow");
        }
        debt = uint256(int256(debt) + rateChange);

        i.Art = uint256(int256(i.Art) + dart);

        _logNote("fork", ilk, src, dst, uint256(dink), uint256(dart));
    }

    // ========================================================================
    // INTERNAL HELPERS
    // ========================================================================

    function addInt(uint256 x, int256 y) internal pure returns (uint256 z) {
        if (y >= 0) {
            z = x + uint256(y);
