    /// @dev Receive ether and delegate
    receive() external payable {
        _delegate();
    }

    /// @dev Internal delegate function using inline assembly
    function _delegate() internal virtual {
        assembly {
            // Copy entire calldata to memory starting at position 0
            calldatacopy(0, 0, calldatasize())

            // Delegate call to implementation address (storage slot 0)
            // Arguments: gas, target, input offset, input size, output offset, output size
            let success := delegatecall(
                gas(),
                sload(0),              // implementation address from storage
                0,                     // input starts at memory position 0
                calldatasize(),        // input size
                0,                     // output starts at memory position 0
                0                      // output size (0 = dynamic)
            )

            // Copy returndata to memory
            returndatacopy(0, 0, returndatasize())

            // Handle delegate call result
            switch success
            case 0 {
                // Revert with return data on failure
                revert(0, returndatasize())
            }
            default {
                // Return return data on success
                return(0, returndatasize())
            }
        }
