// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title EIP-1967 Upgradeable Proxy with Multi-Implementation Support
 * @dev Extended proxy that supports registering multiple implementations
 *      with specific function selectors per implementation address.
 */
contract UpgradeableProxy {
    // ========================================================================
    // STORAGE SLOTS (EIP-1967 Standard)
    // ========================================================================

    /// @notice EIP-1967 Implementation slot: 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc
    /// @dev keccak256("eip1967.proxy.implementation") - 1
    bytes32 private constant IMPLEMENTATION_SLOT = 
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    /// @notice EIP-1967 Admin slot: 0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103
    /// @dev keccak256("eip1967.proxy.admin") - 1
    bytes32 private constant ADMIN_SLOT = 
        0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103;

    /// @notice Mapping: implementation address -> function selector -> implementation exists
    /// @dev Storage pattern: stor[implAddress][keccak256("eip1967.proxy.implementation")]
    mapping(address => mapping(bytes32 => uint256)) private implementationSelectors;

    /// @notice Mapping: function selector -> registered implementation address
    /// @dev Storage pattern: stor[selector | IMPLEMENTATION_SLOT_SUFFIX]
    mapping(bytes4 => address) private selectorToImplementation;

    // ========================================================================
    // EVENTS
    // ========================================================================

    event AdminChanged(address previousAdmin, address newAdmin);
    event Upgraded(address indexed implementation);
    event ImplementationRemoved(address indexed implementation);
    event SelectorsRegistered(address indexed implementation, bytes4[] selectors);

    // ========================================================================
    // ERRORS
    // ========================================================================

    error OnlyAdmin();
    error ZeroAddress();
    error ImplementationNotFound();
    error NoSelectors();
    error ArrayOutOfBounds();
    error ArithmeticOverflow();

    // ========================================================================
    // MODIFIERS
    // ========================================================================

    modifier onlyAdmin() {
        if (_getAdmin() != msg.sender) {
            revert OnlyAdmin();
        }
        _;
    }

    // ========================================================================
    // CONSTRUCTOR (Implicit - Storage Layout Preserved)
    // ========================================================================

    // Note: This is a proxy contract. Initialization happens via the 
    // implementation contract's initialize() function after deployment.

    // ========================================================================
    // VIEW FUNCTIONS
    // ========================================================================

    /// @notice Get the current admin address
    /// @return admin The admin address
    function admin() external view returns (address) {
        return _getAdmin();
    }

    /// @notice Get the current implementation address
    /// @return implementation The implementation address
    function implementation() external view returns (address) {
        return _getImplementation();
    }

    /// @notice Get implementation address for a specific function selector
    /// @param selector The function selector (first 4 bytes of calldata)
    /// @return impl The registered implementation address
    function getImplementationBySelector(bytes4 selector) external view returns (address) {
        return selectorToImplementation[selector];
    }

    /// @notice Check if implementation has registered selectors
    /// @param impl The implementation address
    /// @return count Number of registered selectors
    function getSelectorCount(address impl) external view returns (uint256) {
        return implementationSelectors[impl][IMPLEMENTATION_SLOT];
    }

    /// @notice Get implementation info with selectors for an address
    /// @param impl The implementation address
    /// @return selectors Array of registered function selectors
    function getImplementationInfo(address impl) external view returns (bytes4[] memory) {
        uint256 count = implementationSelectors[impl][IMPLEMENTATION_SLOT];
        bytes4[] memory selectors = new bytes4[](count);

        for (uint256 i = 0; i < count; i++) {
            bytes32 selectorSlot = IMPLEMENTATION_SLOT | bytes32(i);
            selectors[i] = bytes4(implementationSelectors[impl][selectorSlot]);
        }

        return selectors;
    }

    // ========================================================================
    // ADMIN FUNCTIONS
    // ========================================================================

    /// @notice Set a new implementation address (upgrade)
    /// @param newImplementation The new implementation contract address
    function upgradeTo(address newImplementation) external onlyAdmin {
        if (newImplementation == address(0)) {
            revert ZeroAddress();
        }

        address oldImplementation = _getImplementation();
        _setImplementation(newImplementation);

        emit Upgraded(newImplementation);
    }

    /// @notice Set a new admin address
    /// @param newAdmin The new admin address
    function changeAdmin(address newAdmin) external onlyAdmin {
        if (newAdmin == address(0)) {
            revert ZeroAddress();
        }

        address oldAdmin = _getAdmin();
        _setAdmin(newAdmin);

        emit AdminChanged(oldAdmin, newAdmin);
    }

    /// @notice Remove an implementation registration and its selectors
    /// @param impl The implementation address to remove
    function removeImplementation(address impl) external onlyAdmin {
        uint256 count = implementationSelectors[impl][IMPLEMENTATION_SLOT];

        if (count == 0) {
            revert ImplementationNotFound();
        }

        // Clear all registered selectors for this implementation
        for (uint256 i = 0; i < count; i++) {
            bytes32 selectorSlot = IMPLEMENTATION_SLOT | bytes32(i);
            bytes4 selector = bytes4(implementationSelectors[impl][selectorSlot]);

            // Clear the selector mapping
            delete selectorToImplementation[selector];

            // Clear the implementation's selector storage
            delete implementationSelectors[impl][selectorSlot];
        }

        // Clear the count
        delete implementationSelectors[impl][IMPLEMENTATION_SLOT];

        emit ImplementationRemoved(impl);
    }

    /// @notice Register multiple function selectors for an implementation
    /// @param impl The implementation address
    /// @param selectors Array of function selectors to register
    function registerSelectors(address impl, bytes4[] calldata selectors) external onlyAdmin {
        uint256 count = selectors.length;

        if (count == 0) {
            revert NoSelectors();
        }

        // Get current count for this implementation
        uint256 currentCount = implementationSelectors[impl][IMPLEMENTATION_SLOT];

        // Register each selector
        for (uint256 i = 0; i < count; i++) {
            bytes4 selector = selectors[i];
            bytes32 selectorSlot = IMPLEMENTATION_SLOT | bytes32(currentCount + i);

            // Store selector in implementation's mapping
            implementationSelectors[impl][selectorSlot] = bytes32(selector);

            // Map selector to implementation
            selectorToImplementation[selector] = impl;
        }

        // Update the count
        implementationSelectors[impl][IMPLEMENTATION_SLOT] = currentCount + count;

        emit SelectorsRegistered(impl, selectors);
    }

    // ========================================================================
    // FALLBACK FUNCTION (DELEGATECALL)
    // ========================================================================

    /// @notice Fallback function that delegates to implementation
    /// @dev Checks for selector-specific implementation first, then falls back
    ///      to the main implementation slot
    fallback() external payable {
        bytes4 selector = msg.sig;
        address impl = selectorToImplementation[selector];

        // If no selector-specific implementation, use main implementation
        if (impl == address(0)) {
            impl = _getImplementation();
        }

        // Revert if no implementation found
        if (impl == address(0)) {
            revert ImplementationNotFound();
        }

        // Delegate call to implementation
        assembly {
            calldatacopy(0, 0, calldatasize())

            let success := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())

            if eq(success, 0) {
                revert(0, returndatasize())
            }

            return(0, returndatasize())
        }
    }

    receive() external payable {}

    // ========================================================================
    // INTERNAL FUNCTIONS
    // ========================================================================

    /// @notice Get admin from storage
    /// @return adm The admin address
    function _getAdmin() internal view returns (address adm) {
        assembly {
            adm := sload(ADMIN_SLOT)
        }
    }

    /// @notice Set admin in storage
    /// @param newAdmin The new admin address
    function _setAdmin(address newAdmin) internal {
        assembly {
            sstore(ADMIN_SLOT, newAdmin)
        }
    }

    /// @notice Get implementation from storage
    /// @return impl The implementation address
    function _getImplementation() internal view returns (address impl) {
        assembly {
            impl := sload(IMPLEMENTATION_SLOT)
        }
    }

    /// @notice Set implementation in storage
    /// @param newImplementation The new implementation address
    function _setImplementation(address newImplementation) internal {
        assembly {
            sstore(IMPLEMENTATION_SLOT, newImplementation)
        }
    }
}
```

## Key Observations

| Feature | Description |
|---------|-------------|
| **EIP-1967 Compliant** | Uses standard storage slots for `implementation` and `admin` |
| **Multi-Implementation Support** | Can register multiple implementations with specific function selectors |
| **Selector Routing** | Falls back through selector-specific → main implementation |
| **Admin Protection** | All state-changing functions require admin authorization |
| **Zero Address Checks** | Prevents setting admin/implementation to address(0) |

## Storage Layout

```
Slot 0x3608...2bbc ─┬─> implementation (address)
                   └─> implementationSelectors[impl][slot] (mapping)

Slot 0xb531...6103 ─> admin (address)

Slot 0x3ba1...2bbc ─> selectorToImplementation[bytes4] (mapping)
```

This is essentially an **EIP-1967 Proxy with Diamond-like selector routing capabilities**, allowing different functions to delegate to different implementation contracts.

