     *      This is a convenience function to avoid race conditions with approve().
     */
    function increaseApproval(address _spender, uint256 _addedValue) external returns (bool) {
        // Overflow check (redundant in Solidity 0.8+, but matches original bytecode behavior)
        require(allowances[msg.sender][_spender] + _addedValue >= allowances[msg.sender][_spender], 
                "Allowance overflow");

        allowances[msg.sender][_spender] += _addedValue;

        emit Approval(msg.sender, _spender, allowances[msg.sender][_spender]);
        return true;
    }

    /**
