        require(_to != address(0), "Invalid recipient address");
        require(_to != address(this), "Cannot transfer to contract itself");
        require(_value <= balances[msg.sender], "Insufficient balance");

        // Update balances
        balances[msg.sender] -= _value;
        require(balances[_to] + _value >= balances[_to], "Balance overflow");
        balances[_to] += _value;

        // Emit both standard Transfer and ERC677 Transfer events
        emit Transfer(msg.sender, _to, _value);
        emit Transfer(msg.sender, _to, _value, _data);

        // Call tokenFallback on recipient if it's a contract
        if (_to.code.length > 0) {
            (bool success, ) = _to.call(
                abi.encodeWithSignature(
                    "tokenFallback(address,uint256,bytes)",
                    msg.sender,
                    _value,
                    _data
                )
            );
            require(success, "tokenFallback call failed");
        }

        return true;
    }

