    /// @notice Get allowance between owner and spender
    function allowance(address owner, address spender) external view returns (uint256) {
        return _allowances[owner][spender];
    }

    /// @notice Get authorization status of an address
    function isAuthorized(address addr) external view returns (uint256) {
        return _authorizations[addr];
    }

    /// @notice Get permit nonce for an address
    function nonces(address owner) external view returns (uint256) {
        return _nonces[owner];
    }

    /// @notice Get current implementation address
    function implementation() external view returns (address) {
        return _implementation;
    }

    // ============================================
    // AUTHORIZATION FUNCTIONS
    // ============================================

    /// @notice Grant authorization to an address
    /// @dev Only callable by authorized addresses
    function rely(address usr) external {
        require(_authorizations[msg.sender] == 1, "Usds/not-authorized");
        _authorizations[usr] = 1;
        emit Rely(usr);
    }

    /// @notice Revoke authorization from an address
    /// @dev Only callable by authorized addresses
    function deny(address usr) external {
        require(_authorizations[msg.sender] == 1, "Usds/not-authorized");
        _authorizations[usr] = 0;
        emit Deny(usr);
    }

    // ============================================
    // ERC20 FUNCTIONS
    // ============================================

    /// @notice Approve spender to spend tokens
    function approve(address spender, uint256 amount) external returns (bool) {
        _allowances[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    /// @notice Transfer tokens to recipient
    function transfer(address recipient, uint256 amount) external returns (bool) {
        require(recipient != address(0), "Usds/invalid-address");
        require(recipient != address(this), "Usds/invalid-address");
        require(_balances[msg.sender] >= amount, "Usds/insufficient-balance");

        _balances[msg.sender] -= amount;
        _balances[recipient] += amount;

        emit Transfer(msg.sender, recipient, amount);
        return true;
    }

    /// @notice Transfer tokens from sender to recipient
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        require(recipient != address(0), "Usds/invalid-address");
        require(recipient != address(this), "Usds/invalid-address");
        require(_balances[sender] >= amount, "Usds/insufficient-balance");

        // Check allowance if not transferring from self
        if (sender != msg.sender) {
            uint256 currentAllowance = _allowances[sender][msg.sender];
            if (currentAllowance != type(uint256).max) {
                require(currentAllowance >= amount, "Usds/insufficient-allowance");
                _allowances[sender][msg.sender] = currentAllowance - amount;
            }
        }

        _balances[sender] -= amount;
        _balances[recipient] += amount;

        emit Transfer(sender, recipient, amount);
        return true;
    }

    // ============================================
    // MINT/BURN FUNCTIONS
    // ============================================

    /// @notice Mint new tokens to an address
    /// @dev Only callable by authorized addresses
    function mint(address to, uint256 amount) external {
        require(_authorizations[msg.sender] == 1, "Usds/not-authorized");
        require(to != address(0), "Usds/invalid-address");
        require(to != address(this), "Usds/invalid-address");

        _balances[to] += amount;

        // Overflow check
        require(totalSupply + amount >= totalSupply, "overflow");
        totalSupply += amount;

        emit Transfer(address(0), to, amount);
    }

    /// @notice Burn tokens from an address
    /// @dev Can burn own tokens or use allowance for others
    function burn(address from, uint256 amount) external {
        require(_balances[from] >= amount, "Usds/insufficient-balance");

        // Check allowance if not burning from self
        if (from != msg.sender) {
            uint256 currentAllowance = _allowances[from][msg.sender];
            if (currentAllowance != type(uint256).max) {
                require(currentAllowance >= amount, "Usds/insufficient-allowance");
                _allowances[from][msg.sender] = currentAllowance - amount;
            }
        }

        _balances[from] -= amount;
        totalSupply -= amount;

        emit Transfer(from, address(0), amount);
    }

    // ============================================
    // EIP-2612 PERMIT
    // ============================================

    /// @notice Permit spending via signature
    function permit(
        address owner,
        address spender,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        require(block.timestamp <= deadline, "Usds/permit-expired");
        require(owner != address(0), "Usds/invalid-owner");

        // Increment nonce
        _nonces[owner]++;

        // Verify signature
        bytes32 digest = keccak256(
            abi.encodePacked(
                "\x19\x01",
                DOMAIN_SEPARATOR,
                keccak256(
                    abi.encode(
                        PERMIT_TYPEHASH,
                        owner,
                        spender,
                        value,
                        _nonces[owner] - 1,
                        deadline
                    )
                )
            )
        );

        address signer = ecrecover(digest, v, r, s);
        require(signer != address(0) && signer == owner, "INVALID_SIGNATURE");

        _allowances[owner][spender] = value;
        emit Approval(owner, spender, value);
    }

    // ============================================
    // INITIALIZATION
    // ============================================

    /// @notice Initialize the contract (proxy pattern)
    function initialize() external {
        // Initialization logic with flag checks
        // Prevents re-initialization
        assembly {
            let flags := sload(0xf0c57e16840df040f15088dc2f81fe391c3923bec73e23a9662efc9c229c6a00)
            if iszero(and(flags, 1)) {
                sstore(0xf0c57e16840df040f15088dc2f81fe391c3923bec73e23a9662efc9c229c6a00, or(flags, 1))
            }
        }

        _authorizations[msg.sender] = 1;
        emit Rely(msg.sender);
    }

    // ============================================
    // UPGRADE FUNCTION (EIP-1967)
    // ============================================

    /// @notice Upgrade implementation and optionally call it
    /// @dev Only callable by authorized addresses
    function upgradeToAndCall(address newImplementation, bytes calldata data) external payable {
        require(_authorizations[msg.sender] == 1, "Usds/not-authorized");

        // Verify new implementation is proxiable
        (bool success, bytes memory returnData) = newImplementation.staticcall(
            abi.encodeWithSelector(PROXIABLE_UUID)
        );
        require(success, "upgrade failed");
        require(returnData.length >= 32, "invalid response");

        bytes32 uuid = abi.decode(returnData, (bytes32));
        require(uuid == PROXIABLE_UUID, "not proxiable");

        // Require specific implementation address (contract-specific check)
        require(newImplementation == 0x1923dfee706a8e78157416c29cbccfde7cdf4102, "invalid implementation");

        // Store new implementation
        _implementation = newImplementation;
        emit Upgraded(newImplementation);

        // Execute optional call data
        if (data.length > 0) {
            require(msg.value == 0, "cannot send value with data");
            (success, returnData) = newImplementation.delegatecall(data);
            require(success, string(returnData));
        }
    }

    // ============================================
    // EVENTS
    // ============================================

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Rely(address indexed usr);
    event Deny(address indexed usr);
    event Upgraded(address indexed implementation);

    // ============================================
    // FALLBACK
    // ============================================

    receive() external payable {
        revert();
    }

    fallback() external payable {
        revert();
    }
}
```

## Key Features Identified

| Feature | Description |
|---------|-------------|
| **ERC20 Standard** | Full `transfer`, `transferFrom`, `approve`, `balanceOf`, `allowance` |
| **EIP-2612 Permit** | Gasless approvals via signature (`permit` function) |
| **EIP-1967 Proxy** | Upgradeable via `upgradeToAndCall` with implementation slot |
| **Authorization System** | Custom access control via `_authorizations` mapping (`rely`/`deny`) |
| **Mint/Burn** | Authorized minting, permissioned burning with allowance support |
| **Overflow Protection** | Explicit checks on supply modifications |
| **Address Validation** | Prevents transfers/mints to zero address or contract itself |

