# Clean Solidity Translation - MakerDAO PSM Adapter Contract

Based on the Panoramix decompilation, this is a **PSM (Peg Stability Module) adapter contract** that facilitates USDC/USDS swaps through MakerDAO's system. Here's the cleaned-up Solidity code:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title LITE-PSM-USDC-A Adapter
 * @notice Wrapper contract for interacting with MakerDAO's Peg Stability Module
 */
contract LitePSMUSDCAdapter {

    // ============================================================================
    // CONSTANTS
    // ============================================================================

    address public constant PSM           = 0xf6e72db5454dd049d0788e411b06cfaf16853042;
    address public constant VAT           = 0x35d1b3f3d7966a1dfe207aa4514c12a259a0492b;
    address public constant USDS          = 0xdc035d45d973e3ec169d2276ddab16f1e407384f;
    address public constant USDC          = 0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48;
    address public constant GEM_JOIN      = 0x9759a6ac90977b93b58547b4a71c78317f391a28;
    address public constant ADAPTER       = 0x3c0f895007ca717aa01c8693e59df1e8c3777feb;

    bytes32  public constant ILK         = "LITE-PSM-USDC-A";
    uint256  public constant PRECISION   = 1e12;  // USDC (6 dec) → WAD (18 dec) conversion

    // ============================================================================
    // FUNCTION SELECTORS (for external calls)
    // ============================================================================

    bytes4 private constant SELECTOR_PSM_FAE036D5 = 0xfae036d5;
    bytes4 private constant SELECTOR_PSM_95991276 = 0x95991276;
    bytes4 private constant SELECTOR_PSM_8D7EF9BB = 0x8d7ef9bb;
    bytes4 private constant SELECTOR_ADAPTER_EF693BED = 0xef693bed;

    // ============================================================================
    // FALLBACK
    // ============================================================================

    receive() external payable {
        revert("No ETH accepted");
    }

    fallback() external payable {
        revert("Unknown function");
    }

    // ============================================================================
    // EXTERNAL FUNCTIONS
    // ============================================================================

    /**
     * @notice Swap USDC for USDS through the PSM
     * @param usr The recipient address
     * @param wad The amount of USDC (in 6 decimal precision)
     * @return The amount of USDS received
     */
    function swapUSDCForUSDS(address usr, uint256 wad) external payable returns (uint256) {
        // Validate input
        require(msg.data.length >= 68, "Invalid calldata");
        require(usr == address(uint160(usr)), "Invalid address");

        // Ensure USDC contract exists
        require(USDC.code.length > 0, "USDC not deployed");

        // Transfer USDC from caller to this contract
        (bool success1, bytes memory returnData1) = USDC.call(
            abi.encodeWithSelector(
                IERC20.transferFrom.selector,
                msg.sender,
                address(this),
                wad
            )
        );
        require(success1, "USDC transfer failed");

        // Call PSM to process the swap
        (bool success2, bytes memory returnData2) = PSM.call(
            abi.encodeWithSelector(
                SELECTOR_PSM_95991276,
                address(this),
                wad
            )
        );
        require(success2, "PSM call failed");
        require(returnData2.length >= 32, "Invalid PSM response");

        uint256 gemAmount = abi.decode(returnData2, (uint256));

        // Join gems to vat
        require(GEM_JOIN.code.length > 0, "GemJoin not deployed");
        (bool success3, ) = GEM_JOIN.call(
            abi.encodeWithSignature(
                "join(address,uint256)",
                address(this),
                gemAmount
            )
        );
        require(success3, "GemJoin failed");

        // Final adapter processing
        require(ADAPTER.code.length > 0, "Adapter not deployed");
        (bool success4, bytes memory returnData4) = ADAPTER.call(
            abi.encodeWithSelector(
                SELECTOR_ADAPTER_EF693BED,
                usr,
                gemAmount
            )
        );
        require(success4, "Adapter call failed");

        return abi.decode(returnData4, (uint256));
    }

    /**
     * @notice Swap USDS for USDC through the PSM (with fee calculation)
     * @param usr The recipient address  
     * @param wad The amount of USDS (in 18 decimal precision)
     * @return The amount of USDC to receive
     */
    function swapUSDSForUSDC(address usr, uint256 wad) external payable returns (uint256) {
        // Validate input
        require(msg.data.length >= 68, "Invalid calldata");
        require(usr == address(uint160(usr)), "Invalid address");

        // Overflow check for precision multiplication
        require(
            (PRECISION * wad) / wad == PRECISION || wad == 0,
            "Overflow detected"
        );

        // Query PSM for rate information
        (bool success1, bytes memory returnData1) = PSM.staticcall(
            abi.encodeWithSelector(SELECTOR_PSM_FAE036D5)
        );
        require(success1, "PSM staticcall failed");
        require(returnData1.length >= 32, "Invalid PSM response");

        uint256 rate = abi.decode(returnData1, (uint256));

        // Calculate output amount with fee
        // Formula: (PRECISION * rate * wad / 1e18) + (PRECISION * wad)
        uint256 numerator = PRECISION * rate * wad;
        require(numerator / rate == PRECISION * wad, "Multiplication overflow");

        uint256 usdcAmount = (numerator / 1e18) + (PRECISION * wad);

        // Validate calculation
        require(
            (PRECISION * wad) <= usdcAmount && 
            (PRECISION * wad) != 0,
            "Invalid calculation"
        );

        // Transfer USDS from caller to this contract
        require(USDS.code.length > 0, "USDS not deployed");
        (bool success2, ) = USDS.call(
            abi.encodeWithSelector(
                IERC20.transferFrom.selector,
                msg.sender,
                address(this),
                usdcAmount
            )
        );
        require(success2, "USDS transfer failed");

        // Join USDS to vat
        require(ADAPTER.code.length > 0, "Adapter not deployed");
        (bool success3, ) = ADAPTER.call(
            abi.encodeWithSignature(
                "join(address,uint256)",
                address(this),
                usdcAmount
            )
        );
        require(success3, "Adapter join failed");

        // Exit gems from vat
        require(GEM_JOIN.code.length > 0, "GemJoin not deployed");
        (bool success4, ) = GEM_JOIN.call(
            abi.encodeWithSelector(
                SELECTOR_ADAPTER_EF693BED,
                address(this),
                usdcAmount
            )
        );
        require(success4, "Gem exit failed");

        // Finalize swap through PSM
        (bool success5, bytes memory returnData5) = PSM.call(
            abi.encodeWithSelector(
                SELECTOR_PSM_8D7EF9BB,
                usr,
                wad
            )
        );
        require(success5, "PSM finalization failed");
        require(returnData5.length >= 32, "Invalid PSM response");

        return usdcAmount;
    }
}

// ============================================================================
// INTERFACES
// ============================================================================

interface IERC20 {
    function transferFrom(address sender, address recipient, uint256 amount) 
        external 
        returns (bool);
}
```

## Key Observations

| Component | Address | Purpose |
|-----------|---------|---------|
| **PSM** | `0xf6e7...3042` | Peg Stability Module core |
| **USDC** | `0xa0b8...eb48` | Input stablecoin (6 decimals) |
| **USDS** | `0xdc03...384f` | Output stablecoin (18 decimals) |
| **GEM_JOIN** | `0x9759...1a28` | Vat join interface |
| **ADAPTER** | `0x3c0f...7feb` | Additional processing layer |

## Architecture Notes

1. **Precision Handling**: Uses `1e12` multiplier to convert between USDC (6 decimals) and internal WAD precision (18 decimals)

2. **Two Swap Directions**:
   - `swapUSDCForUSDS()` - Mint USDS from USDC
   - `swapUSDSForUSDC()` - Redeem USDC from USDS (includes fee calculation)

3. **Security Checks**: Validates contract existence via `ext_code.size`, performs overflow checks, and verifies return data lengths

4. **Call Pattern**: Follows MakerDAO's standard `transferFrom → join → process → return` flow
